1  import {useFocusEffect, useRoute} from '@react-navigation/native';
     2  import React, {useCallback, useEffect, useMemo, useRef, useState} from 'react';
     3  import {ActivityIndicator, View} from 'react-native';
     4  import {useOnyx} from 'react-native-onyx';
     5  import Button from '@components/Button';
     6  import CollapsibleSection from '@components/CollapsibleSection';
     7  import ConfirmModal from '@components/ConfirmModal';
     8  import FormHelpMessage from '@components/FormHelpMessage';
     9  import HeaderWithBackButton from '@components/HeaderWithBackButton';
    10  import * as Expensicons from '@components/Icon/Expensicons';
    11  import * as Illustrations from '@components/Icon/Illustrations';
    12  import MenuItem from '@components/MenuItem';
    13  import MenuItemList from '@components/MenuItemList';
    14  import type {MenuItemWithLink} from '@components/MenuItemList';
    15  import OfflineWithFeedback from '@components/OfflineWithFeedback';
    16  import ScreenWrapper from '@components/ScreenWrapper';
    17  import ScrollView from '@components/ScrollView';
    18  import Section from '@components/Section';
    19  import Text from '@components/Text';
    20  import TextLink from '@components/TextLink';
    21  import ThreeDotsMenu from '@components/ThreeDotsMenu';
    22  import type ThreeDotsMenuProps from '@components/ThreeDotsMenu/types';
    23  import useLocalize from '@hooks/useLocalize';
    24  import useNetwork from '@hooks/useNetwork';
    25  import usePermissions from '@hooks/usePermissions';
    26  import useResponsiveLayout from '@hooks/useResponsiveLayout';
    27  import useTheme from '@hooks/useTheme';
    28  import useThemeStyles from '@hooks/useThemeStyles';
    29  import useWindowDimensions from '@hooks/useWindowDimensions';
    30  import {isAuthenticationError, isConnectionInProgress, isConnectionUnverified, removePolicyConnection, syncConnection} from '@libs/actions/connections';
    31  import * as PolicyUtils from '@libs/PolicyUtils';
    32  import {
    33      areSettingsInErrorFields,
    34      findCurrentXeroOrganization,
    35      getConnectedIntegration,
    36      getCurrentSageIntacctEntityName,
    37      getCurrentXeroOrganizationName,
    38      getIntegrationLastSuccessfulDate,
    39      getXeroTenants,
    40      isControlPolicy,
    41      settingsPendingAction,
    42  } from '@libs/PolicyUtils';
    43  import Navigation from '@navigation/Navigation';
    44  import AccessOrNotFoundWrapper from '@pages/workspace/AccessOrNotFoundWrapper';
    45  import withPolicyConnections from '@pages/workspace/withPolicyConnections';
    46  import type {AnchorPosition} from '@styles/index';
    47  import * as Link from '@userActions/Link';
    48  import CONST from '@src/CONST';
    49  import ONYXKEYS from '@src/ONYXKEYS';
    50  import ROUTES from '@src/ROUTES';
    51  import type {ConnectionName} from '@src/types/onyx/Policy';
    52  import {isEmptyObject} from '@src/types/utils/EmptyObject';
    53  import {AccountingContextProvider, useAccountingContext} from './AccountingContext';
    54  import type {MenuItemData, PolicyAccountingPageProps} from './types';
    55  import {getAccountingIntegrationData, getSynchronizationErrorMessage} from './utils';
    56
    57  type RouteParams = {
    58      newConnectionName?: ConnectionName;
    59      integrationToDisconnect?: ConnectionName;
    60      shouldDisconnectIntegrationBeforeConnecting?: boolean;
    61  };
    62
    63  function PolicyAccountingPage({policy}: PolicyAccountingPageProps) {
    64      const [connectionSyncProgress] = useOnyx(`${ONYXKEYS.COLLECTION.POLICY_CONNECTION_SYNC_PROGRESS}${policy?.id}`);
    65      const theme = useTheme();
    66      const styles = useThemeStyles();
    67      const {translate, datetimeToRelative: getDatetimeToRelative} = useLocalize();
    68      const {isOffline} = useNetwork();
    69      const {canUseNetSuiteUSATax} = usePermissions();
    70      const {windowWidth} = useWindowDimensions();
    71      const {shouldUseNarrowLayout} = useResponsiveLayout();
    72      const [threeDotsMenuPosition, setThreeDotsMenuPosition] = useState<AnchorPosition>({horizontal: 0, vertical: 0});
    73      const [isDisconnectModalOpen, setIsDisconnectModalOpen] = useState(false);
    74      const [datetimeToRelative, setDateTimeToRelative] = useState('');
    75      const threeDotsMenuContainerRef = useRef<View>(null);
    76      const {canUseNewDotQBD} = usePermissions();
    77      const {startIntegrationFlow, popoverAnchorRefs} = useAccountingContext();
    78
    79      const route = useRoute();
    80      const params = route.params as RouteParams | undefined;
    81      const newConnectionName = params?.newConnectionName;
    82      const integrationToDisconnect = params?.integrationToDisconnect;
    83      const shouldDisconnectIntegrationBeforeConnecting = params?.shouldDisconnectIntegrationBeforeConnecting;
    84
    85      const isSyncInProgress = isConnectionInProgress(connectionSyncProgress, policy);
    86
    87      const {QBD: qbdConnectionName, ...allConnectionNamesWithoutQBD} = CONST.POLICY.CONNECTIONS.NAME;
    88      const connectionNames = canUseNewDotQBD ? CONST.POLICY.CONNECTIONS.NAME : allConnectionNamesWithoutQBD;
    89      const accountingIntegrations = Object.values(connectionNames);
    90      const connectedIntegration = getConnectedIntegration(policy, accountingIntegrations) ?? connectionSyncProgress?.connectionName;
    91      const synchronizationError = connectedIntegration && getSynchronizationErrorMessage(policy, connectedIntegration, isSyncInProgress, translate, styles);
    92
    93      const shouldShowEnterCredentials = connectedIntegration && !!synchronizationError && isAuthenticationError(policy, connectedIntegration);
    94
    95      const policyID = policy?.id ?? '-1';
    96      // Get the last successful date of the integration. Then, if `connectionSyncProgress` is the same integration displayed and the state is 'jobDone', get the more recent update time of the two.
    97      const successfulDate = getIntegrationLastSuccessfulDate(
    98          connectedIntegration ? policy?.connections?.[connectedIntegration] : undefined,
    99          connectedIntegration === connectionSyncProgress?.connectionName ? connectionSyncProgress : undefined,
   100      );
   101
   102      const hasSyncError = PolicyUtils.hasSyncError(policy, isSyncInProgress);
   103      const hasUnsupportedNDIntegration = !isEmptyObject(policy?.connections) && PolicyUtils.hasUnsupportedIntegration(policy, accountingIntegrations);
   104
   105      const tenants = useMemo(() => getXeroTenants(policy), [policy]);
   106      const currentXeroOrganization = findCurrentXeroOrganization(tenants, policy?.connections?.xero?.config?.tenantID);
   107      const shouldShowSynchronizationError = !!synchronizationError;
   108      const shouldShowReinstallConnectorMenuItem = shouldShowSynchronizationError && connectedIntegration === CONST.POLICY.CONNECTIONS.NAME.QBD;
   109
   110      const overflowMenu: ThreeDotsMenuProps['menuItems'] = useMemo(
   111          () => [
   112              ...(shouldShowReinstallConnectorMenuItem
   113                  ? [
   114                        {
   115                            icon: Expensicons.CircularArrowBackwards,
   116                            text: translate('workspace.accounting.reinstall'),
   117                            onSelected: () => startIntegrationFlow({name: CONST.POLICY.CONNECTIONS.NAME.QBD}),
   118                            shouldCallAfterModalHide: true,
   119                            disabled: isOffline,
   120                            iconRight: Expensicons.NewWindow,
   121                        },
   122                    ]
   123                  : []),
   124              ...(shouldShowEnterCredentials && (connectedIntegration === CONST.POLICY.CONNECTIONS.NAME.SAGE_INTACCT || connectedIntegration === CONST.POLICY.CONNECTIONS.NAME.NETSUITE)
   125                  ? [
   126                        {
   127                            icon: Expensicons.Key,
   128                            text: translate('workspace.accounting.enterCredentials'),
   129                            onSelected: () => startIntegrationFlow({name: connectedIntegration}),
   130                            shouldCallAfterModalHide: true,
   131                            disabled: isOffline,
   132                            iconRight: Expensicons.NewWindow,
   133                        },
   134                    ]
   135                  : [
   136                        {
   137                            icon: Expensicons.Sync,
   138                            text: translate('workspace.accounting.syncNow'),
   139                            onSelected: () => syncConnection(policyID, connectedIntegration),
   140                            disabled: isOffline,
   141                        },
   142                    ]),
   143              {
   144                  icon: Expensicons.Trashcan,
   145                  text: translate('workspace.accounting.disconnect'),
   146                  onSelected: () => setIsDisconnectModalOpen(true),
   147                  shouldCallAfterModalHide: true,
   148              },
   149          ],
   150          [shouldShowEnterCredentials, shouldShowReinstallConnectorMenuItem, translate, isOffline, policyID, connectedIntegration, startIntegrationFlow],
   151      );
   152
   153      useFocusEffect(
   154          useCallback(() => {
   155              if (!newConnectionName || !isControlPolicy(policy)) {
   156                  return;
   157              }
   158
   159              startIntegrationFlow({
   160                  name: newConnectionName,
   161                  integrationToDisconnect,
   162                  shouldDisconnectIntegrationBeforeConnecting,
   163              });
   164          }, [newConnectionName, integrationToDisconnect, shouldDisconnectIntegrationBeforeConnecting, policy, startIntegrationFlow]),
   165      );
   166
   167      useEffect(() => {
   168          if (successfulDate) {
   169              setDateTimeToRelative(getDatetimeToRelative(successfulDate));
   170              return;
   171          }
   172          setDateTimeToRelative('');
   173      }, [getDatetimeToRelative, successfulDate]);
   174
   175      const integrationSpecificMenuItems = useMemo(() => {
   176          const sageIntacctEntityList = policy?.connections?.intacct?.data?.entities ?? [];
   177          const netSuiteSubsidiaryList = policy?.connections?.netsuite?.options?.data?.subsidiaryList ?? [];
   178          switch (connectedIntegration) {
   179              case CONST.POLICY.CONNECTIONS.NAME.XERO:
   180                  return !policy?.connections?.xero?.data?.tenants
   181                      ? {}
   182                      : {
   183                            description: translate('workspace.xero.organization'),
   184                            iconRight: Expensicons.ArrowRight,
   185                            title: getCurrentXeroOrganizationName(policy),
   186                            wrapperStyle: [styles.sectionMenuItemTopDescription],
   187                            titleStyle: styles.fontWeightNormal,
   188                            shouldShowRightIcon: tenants.length > 1,
   189                            shouldShowDescriptionOnTop: true,
   190                            onPress: () => {
   191                                if (!(tenants.length > 1)) {
   192                                    return;
   193                                }
   194                                Navigation.navigate(ROUTES.POLICY_ACCOUNTING_XERO_ORGANIZATION.getRoute(policyID, currentXeroOrganization?.id ?? '-1'));
   195                            },
   196                            pendingAction: settingsPendingAction([CONST.XERO_CONFIG.TENANT_ID], policy?.connections?.xero?.config?.pendingFields),
   197                            brickRoadIndicator: areSettingsInErrorFields([CONST.XERO_CONFIG.TENANT_ID], policy?.connections?.xero?.config?.errorFields)
   198                                ? CONST.BRICK_ROAD_INDICATOR_STATUS.ERROR
   199                                : undefined,
   200                        };
   201              case CONST.POLICY.CONNECTIONS.NAME.NETSUITE:
   202                  return !policy?.connections?.netsuite?.options?.config?.subsidiary
   203                      ? {}
   204                      : {
   205                            description: translate('workspace.netsuite.subsidiary'),
   206                            iconRight: Expensicons.ArrowRight,
   207                            title: policy?.connections?.netsuite?.options?.config?.subsidiary ?? '',
   208                            wrapperStyle: [styles.sectionMenuItemTopDescription],
   209                            titleStyle: styles.fontWeightNormal,
   210                            shouldShowRightIcon: netSuiteSubsidiaryList?.length > 1,
   211                            shouldShowDescriptionOnTop: true,
   212                            pendingAction: policy?.connections?.netsuite?.options?.config?.pendingFields?.subsidiary,
   213                            brickRoadIndicator: policy?.connections?.netsuite?.options?.config?.errorFields?.subsidiary ? CONST.BRICK_ROAD_INDICATOR_STATUS.ERROR : undefined,
   214                            onPress: () => {
   215                                if (!(netSuiteSubsidiaryList?.length > 1)) {
   216                                    return;
   217                                }
   218                                Navigation.navigate(ROUTES.POLICY_ACCOUNTING_NETSUITE_SUBSIDIARY_SELECTOR.getRoute(policyID));
   219                            },
   220                        };
   221              case CONST.POLICY.CONNECTIONS.NAME.SAGE_INTACCT:
   222                  return !sageIntacctEntityList.length
   223                      ? {}
   224                      : {
   225                            description: translate('workspace.intacct.entity'),
   226                            iconRight: Expensicons.ArrowRight,
   227                            title: getCurrentSageIntacctEntityName(policy, translate('workspace.common.topLevel')),
   228                            wrapperStyle: [styles.sectionMenuItemTopDescription],
   229                            titleStyle: styles.fontWeightNormal,
   230                            shouldShowRightIcon: true,
   231                            shouldShowDescriptionOnTop: true,
   232                            pendingAction: policy?.connections?.intacct?.config?.pendingFields?.entity,
   233                            brickRoadIndicator: policy?.connections?.intacct?.config?.errorFields?.entity ? CONST.BRICK_ROAD_INDICATOR_STATUS.ERROR : undefined,
   234                            onPress: () => {
   235                                if (!sageIntacctEntityList.length) {
   236                                    return;
   237                                }
   238                                Navigation.navigate(ROUTES.POLICY_ACCOUNTING_SAGE_INTACCT_ENTITY.getRoute(policyID));
   239                            },
   240                        };
   241              default:
   242                  return undefined;
   243          }
   244      }, [connectedIntegration, currentXeroOrganization?.id, policy, policyID, styles.fontWeightNormal, styles.sectionMenuItemTopDescription, tenants.length, translate]);
   245
   246      const connectionsMenuItems: MenuItemData[] = useMemo(() => {
   247          if (isEmptyObject(policy?.connections) && !isSyncInProgress) {
   248              return accountingIntegrations
   249                  .map((integration) => {
   250                      const integrationData = getAccountingIntegrationData(integration, policyID, translate);
   251                      if (!integrationData) {
   252                          return undefined;
   253                      }
   254                      const iconProps = integrationData?.icon ? {icon: integrationData.icon, iconType: CONST.ICON_TYPE_AVATAR} : {};
   255
   256                      return {
   257                          ...iconProps,
   258                          interactive: false,
   259                          wrapperStyle: [styles.sectionMenuItemTopDescription],
   260                          shouldShowRightComponent: true,
   261                          title: integrationData?.title,
   262                          rightComponent: (
   263                              <Button
   264                                  onPress={() => startIntegrationFlow({name: integration})}
   265                                  text={translate('workspace.accounting.setup')}
   266                                  style={styles.justifyContentCenter}
   267                                  small
   268                                  isDisabled={isOffline}
   269                                  ref={(ref) => {
   270                                      if (!popoverAnchorRefs?.current) {
   271                                          return;
   272                                      }
   273                                      // eslint-disable-next-line react-compiler/react-compiler
   274                                      popoverAnchorRefs.current[integration].current = ref;
   275                                  }}
   276                              />
   277                          ),
   278                      };
   279                  })
   280                  .filter(Boolean) as MenuItemData[];
   281          }
   282
   283          if (!connectedIntegration) {
   284              return [];
   285          }
   286          const shouldHideConfigurationOptions = isConnectionUnverified(policy, connectedIntegration);
   287          const integrationData = getAccountingIntegrationData(connectedIntegration, policyID, translate, policy, undefined, undefined, undefined, canUseNetSuiteUSATax);
   288          const iconProps = integrationData?.icon ? {icon: integrationData.icon, iconType: CONST.ICON_TYPE_AVATAR} : {};
   289
   290          const configurationOptions = [
   291              {
   292                  icon: Expensicons.Pencil,
   293                  iconRight: Expensicons.ArrowRight,
   294                  shouldShowRightIcon: true,
   295                  title: translate('workspace.accounting.import'),
   296                  wrapperStyle: [styles.sectionMenuItemTopDescription],
   297                  onPress: integrationData?.onImportPagePress,
   298                  brickRoadIndicator: areSettingsInErrorFields(integrationData?.subscribedImportSettings, integrationData?.errorFields) ? CONST.BRICK_ROAD_INDICATOR_STATUS.ERROR : undefined,
   299                  pendingAction: settingsPendingAction(integrationData?.subscribedImportSettings, integrationData?.pendingFields),
   300              },
   301              {
   302                  icon: Expensicons.Send,
   303                  iconRight: Expensicons.ArrowRight,
   304                  shouldShowRightIcon: true,
   305                  title: translate('workspace.accounting.export'),
   306                  wrapperStyle: [styles.sectionMenuItemTopDescription],
   307                  onPress: integrationData?.onExportPagePress,
   308                  brickRoadIndicator: areSettingsInErrorFields(integrationData?.subscribedExportSettings, integrationData?.errorFields) ? CONST.BRICK_ROAD_INDICATOR_STATUS.ERROR : undefined,
   309                  pendingAction: settingsPendingAction(integrationData?.subscribedExportSettings, integrationData?.pendingFields),
   310              },
   311              {
   312                  icon: Expensicons.ExpensifyCard,
   313                  iconRight: Expensicons.ArrowRight,
   314                  shouldShowRightIcon: true,
   315                  title: translate('workspace.accounting.cardReconciliation'),
   316                  wrapperStyle: [styles.sectionMenuItemTopDescription],
   317                  onPress: integrationData?.onCardReconciliationPagePress,
   318              },
   319              {
   320                  icon: Expensicons.Gear,
   321                  iconRight: Expensicons.ArrowRight,
   322                  shouldShowRightIcon: true,
   323                  title: translate('workspace.accounting.advanced'),
   324                  wrapperStyle: [styles.sectionMenuItemTopDescription],
   325                  onPress: integrationData?.onAdvancedPagePress,
   326                  brickRoadIndicator: areSettingsInErrorFields(integrationData?.subscribedAdvancedSettings, integrationData?.errorFields) ? CONST.BRICK_ROAD_INDICATOR_STATUS.ERROR : undefined,
   327                  pendingAction: settingsPendingAction(integrationData?.subscribedAdvancedSettings, integrationData?.pendingFields),
   328              },
   329          ];
   330
   331          if (!policy?.areExpensifyCardsEnabled) {
   332              configurationOptions.splice(2, 1);
   333          }
   334
   335          return [
   336              {
   337                  ...iconProps,
   338                  interactive: false,
   339                  wrapperStyle: [styles.sectionMenuItemTopDescription, shouldShowSynchronizationError && styles.pb0],
   340                  shouldShowRightComponent: true,
   341                  title: integrationData?.title,
   342                  errorText: synchronizationError,
   343                  errorTextStyle: [styles.mt5],
   344                  shouldShowRedDotIndicator: true,
   345                  description:
   346                      isSyncInProgress && connectionSyncProgress?.stageInProgress
   347                          ? translate('workspace.accounting.connections.syncStageName', {stage: connectionSyncProgress.stageInProgress})
   348                          : translate('workspace.accounting.lastSync', {relativeDate: datetimeToRelative}),
   349                  rightComponent: isSyncInProgress ? (
   350                      <ActivityIndicator
   351                          style={[styles.popoverMenuIcon]}
   352                          color={theme.spinner}
   353                      />
   354                  ) : (
   355                      <View ref={threeDotsMenuContainerRef}>
   356                          <ThreeDotsMenu
   357                              onIconPress={() => {
   358                                  threeDotsMenuContainerRef.current?.measureInWindow((x, y, width, height) => {
   359                                      setThreeDotsMenuPosition({
   360                                          horizontal: x + width,
   361                                          vertical: y + height,
   362                                      });
   363                                  });
   364                              }}
   365                              menuItems={overflowMenu}
   366                              anchorPosition={threeDotsMenuPosition}
   367                              anchorAlignment={{horizontal: CONST.MODAL.ANCHOR_ORIGIN_HORIZONTAL.RIGHT, vertical: CONST.MODAL.ANCHOR_ORIGIN_VERTICAL.TOP}}
   368                          />
   369                      </View>
   370                  ),
   371              },
   372              ...(isEmptyObject(integrationSpecificMenuItems) || shouldShowSynchronizationError || isEmptyObject(policy?.connections) ? [] : [integrationSpecificMenuItems]),
   373              ...(isEmptyObject(policy?.connections) || shouldHideConfigurationOptions ? [] : configurationOptions),
   374          ];
   375      }, [
   376          policy,
   377          isSyncInProgress,
   378          connectedIntegration,
   379          synchronizationError,
   380          shouldShowSynchronizationError,
   381          policyID,
   382          translate,
   383          styles.sectionMenuItemTopDescription,
   384          styles.pb0,
   385          styles.mt5,
   386          styles.popoverMenuIcon,
   387          styles.justifyContentCenter,
   388          connectionSyncProgress?.stageInProgress,
   389          datetimeToRelative,
   390          theme.spinner,
   391          overflowMenu,
   392          threeDotsMenuPosition,
   393          integrationSpecificMenuItems,
   394          accountingIntegrations,
   395          isOffline,
   396          startIntegrationFlow,
   397          popoverAnchorRefs,
   398          canUseNetSuiteUSATax,
   399      ]);
   400
   401      const otherIntegrationsItems = useMemo(() => {
   402          if (isEmptyObject(policy?.connections) && !isSyncInProgress) {
   403              return;
   404          }
   405          const otherIntegrations = accountingIntegrations.filter(
   406              (integration) => (isSyncInProgress && integration !== connectionSyncProgress?.connectionName) || integration !== connectedIntegration,
   407          );
   408          return otherIntegrations
   409              .map((integration) => {
   410                  const integrationData = getAccountingIntegrationData(integration, policyID, translate);
   411                  if (!integrationData) {
   412                      return undefined;
   413                  }
   414                  const iconProps = integrationData?.icon ? {icon: integrationData.icon, iconType: CONST.ICON_TYPE_AVATAR} : {};
   415
   416                  return {
   417                      ...iconProps,
   418                      title: integrationData?.title,
   419                      rightComponent: (
   420                          <Button
   421                              onPress={() =>
   422                                  startIntegrationFlow({
   423                                      name: integration,
   424                                      integrationToDisconnect: connectedIntegration,
   425                                      shouldDisconnectIntegrationBeforeConnecting: true,
   426                                  })
   427                              }
   428                              text={translate('workspace.accounting.setup')}
   429                              style={styles.justifyContentCenter}
   430                              small
   431                              isDisabled={isOffline}
   432                              ref={(r) => {
   433                                  if (!popoverAnchorRefs?.current) {
   434                                      return;
   435                                  }
   436                                  popoverAnchorRefs.current[integration].current = r;
   437                              }}
   438                          />
   439                      ),
   440                      interactive: false,
   441                      shouldShowRightComponent: true,
   442                      wrapperStyle: styles.sectionMenuItemTopDescription,
   443                  };
   444              })
   445              .filter(Boolean) as MenuItemWithLink[];
   446      }, [
   447          policy?.connections,
   448          isSyncInProgress,
   449          accountingIntegrations,
   450          connectionSyncProgress?.connectionName,
   451          connectedIntegration,
   452          policyID,
   453          translate,
   454          styles.justifyContentCenter,
   455          styles.sectionMenuItemTopDescription,
   456          isOffline,
   457          startIntegrationFlow,
   458          popoverAnchorRefs,
   459      ]);
   460
   461      return (
   462          <AccessOrNotFoundWrapper
   463              accessVariants={[CONST.POLICY.ACCESS_VARIANTS.ADMIN, CONST.POLICY.ACCESS_VARIANTS.PAID]}
   464              policyID={policyID}
   465              featureName={CONST.POLICY.MORE_FEATURES.ARE_CONNECTIONS_ENABLED}
   466          >
   467              <ScreenWrapper
   468                  testID={PolicyAccountingPage.displayName}
   469                  includeSafeAreaPaddingBottom={false}
   470                  shouldShowOfflineIndicatorInWideScreen
   471              >
   472                  <HeaderWithBackButton
   473                      title={translate('workspace.common.accounting')}
   474                      shouldShowBackButton={shouldUseNarrowLayout}
   475                      icon={Illustrations.Accounting}
   476                      threeDotsAnchorPosition={styles.threeDotsPopoverOffsetNoCloseButton(windowWidth)}
   477                  />
   478                  <ScrollView contentContainerStyle={styles.pt3}>
   479                      <View style={[styles.flex1, shouldUseNarrowLayout ? styles.workspaceSectionMobile : styles.workspaceSection]}>
   480                          <Section
   481                              title={translate('workspace.accounting.title')}
   482                              subtitle={translate('workspace.accounting.subtitle')}
   483                              isCentralPane
   484                              subtitleMuted
   485                              titleStyles={styles.accountSettingsSectionTitle}
   486                              childrenStyles={styles.pt5}
   487                          >
   488                              {!hasUnsupportedNDIntegration &&
   489                                  connectionsMenuItems.map((menuItem) => (
   490                                      <OfflineWithFeedback
   491                                          pendingAction={menuItem.pendingAction}
   492                                          key={menuItem.title}
   493                                          shouldDisableStrikeThrough
   494                                      >
   495                                          <MenuItem
   496                                              brickRoadIndicator={menuItem.brickRoadIndicator}
   497                                              key={menuItem.title}
   498                                              // eslint-disable-next-line react/jsx-props-no-spreading
   499                                              {...menuItem}
   500                                          />
   501                                      </OfflineWithFeedback>
   502                                  ))}
   503                              {hasUnsupportedNDIntegration && hasSyncError && (
   504                                  <FormHelpMessage
   505                                      isError
   506                                      style={styles.menuItemError}
   507                                  >
   508                                      <Text style={[{color: theme.textError}]}>
   509                                          {translate('workspace.accounting.errorODIntegration')}
   510                                          <TextLink
   511                                              onPress={() => {
   512                                                  // Go to Expensify Classic.
   513                                                  Link.openOldDotLink(CONST.OLDDOT_URLS.POLICY_CONNECTIONS_URL(policyID));
   514                                              }}
   515                                          >
   516                                              {translate('workspace.accounting.goToODToFix')}
   517                                          </TextLink>
   518                                      </Text>
   519                                  </FormHelpMessage>
   520                              )}
   521                              {hasUnsupportedNDIntegration && !hasSyncError && (
   522                                  <FormHelpMessage shouldShowRedDotIndicator={false}>
   523                                      <Text>
   524                                          <TextLink
   525                                              onPress={() => {
   526                                                  // Go to Expensify Classic.
   527                                                  Link.openOldDotLink(CONST.OLDDOT_URLS.POLICY_CONNECTIONS_URL(policyID));
   528                                              }}
   529                                          >
   530                                              {translate('workspace.accounting.goToODToSettings')}
   531                                          </TextLink>
   532                                      </Text>
   533                                  </FormHelpMessage>
   534                              )}
   535                              {otherIntegrationsItems && (
   536                                  <CollapsibleSection
   537                                      title={translate('workspace.accounting.other')}
   538                                      wrapperStyle={[styles.pr3, styles.mt5, styles.pv3]}
   539                                      titleStyle={[styles.textNormal, styles.colorMuted]}
   540                                      textStyle={[styles.flex1, styles.userSelectNone, styles.textNormal, styles.colorMuted]}
   541                                  >
   542                                      <MenuItemList
   543                                          menuItems={otherIntegrationsItems}
   544                                          shouldUseSingleExecution
   545                                      />
   546                                  </CollapsibleSection>
   547                              )}
   548                          </Section>
   549                      </View>
   550                  </ScrollView>
   551                  <ConfirmModal
